CREATE TYPE "PublicStanceLabel" AS ENUM ('SUPPORTS','OPPOSES','DIFFERENT_APPROACH','NO_PUBLIC_POSITION','DECLINED_TO_STATE');
CREATE TYPE "PublicationStatus" AS ENUM ('DRAFT','PENDING_REVIEW','PUBLISHED','SUPERSEDED','LEGAL_HOLD');
CREATE TABLE "Election" ("id" UUID PRIMARY KEY,"name" TEXT NOT NULL,"cycle" INTEGER NOT NULL,"generalDate" TIMESTAMP(3) NOT NULL,"status" TEXT NOT NULL);
CREATE TABLE "Race" ("id" UUID PRIMARY KEY,"electionId" UUID NOT NULL REFERENCES "Election"("id"),"office" TEXT NOT NULL,"state" TEXT NOT NULL,"district" TEXT,"seatClass" TEXT,"specialFlag" BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE "Candidate" ("id" UUID PRIMARY KEY,"legalName" TEXT NOT NULL,"displayName" TEXT NOT NULL,"partyText" TEXT,"fecCandidateId" TEXT UNIQUE,"incumbentFlag" BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE "RaceCandidate" ("raceId" UUID NOT NULL REFERENCES "Race"("id"),"candidateId" UUID NOT NULL REFERENCES "Candidate"("id"),"ballotStatus" TEXT NOT NULL,"ballotOrder" INTEGER,"withdrawnAt" TIMESTAMP(3),PRIMARY KEY("raceId","candidateId"));
CREATE TABLE "CandidateAccount" ("id" UUID PRIMARY KEY,"candidateId" UUID NOT NULL REFERENCES "Candidate"("id"),"platform" TEXT NOT NULL,"accountId" TEXT NOT NULL,"canonicalUrl" TEXT NOT NULL,"verificationMethod" TEXT NOT NULL,"status" TEXT NOT NULL,UNIQUE("platform","accountId"));
CREATE TABLE "Issue" ("id" UUID PRIMARY KEY,"slug" TEXT NOT NULL UNIQUE,"neutralTitle" TEXT NOT NULL,"publicCategory" TEXT NOT NULL);
CREATE TABLE "IssueVersion" ("id" UUID PRIMARY KEY,"issueId" UUID NOT NULL REFERENCES "Issue"("id"),"cycle" INTEGER NOT NULL,"version" INTEGER NOT NULL,"canonicalQuestion" TEXT NOT NULL,"goal" TEXT NOT NULL,"planJson" JSONB NOT NULL,"effectiveAt" TIMESTAMP(3) NOT NULL,UNIQUE("issueId","version"));
CREATE TABLE "Source" ("id" UUID PRIMARY KEY,"candidateId" UUID NOT NULL REFERENCES "Candidate"("id"),"type" TEXT NOT NULL,"url" TEXT NOT NULL,"platformId" TEXT,"publishedAt" TIMESTAMP(3),"retrievedAt" TIMESTAMP(3) NOT NULL,"hash" TEXT NOT NULL,"archiveRef" TEXT);
CREATE TABLE "SourcePassage" ("id" UUID PRIMARY KEY,"sourceId" UUID NOT NULL REFERENCES "Source"("id"),"startOffset" INTEGER NOT NULL,"endOffset" INTEGER NOT NULL,"text" TEXT NOT NULL,"embeddingRef" TEXT);
CREATE TABLE "Evidence" ("id" UUID PRIMARY KEY,"candidateId" UUID NOT NULL REFERENCES "Candidate"("id"),"issueVersionId" UUID NOT NULL REFERENCES "IssueVersion"("id"),"sourcePassageId" UUID NOT NULL REFERENCES "SourcePassage"("id"),"directness" TEXT NOT NULL,"reviewerNote" TEXT,"approvedAt" TIMESTAMP(3));
CREATE TABLE "Stance" ("id" UUID PRIMARY KEY,"candidateId" UUID NOT NULL REFERENCES "Candidate"("id"),"issueVersionId" UUID NOT NULL REFERENCES "IssueVersion"("id"),"label" "PublicStanceLabel" NOT NULL,"effectiveAt" TIMESTAMP(3) NOT NULL,"supersedesId" UUID REFERENCES "Stance"("id"),"status" "PublicationStatus" NOT NULL);
CREATE INDEX "Stance_candidate_issue_effective_idx" ON "Stance"("candidateId","issueVersionId","effectiveAt");
CREATE TABLE "StanceEvidence" ("stanceId" UUID NOT NULL REFERENCES "Stance"("id"),"evidenceId" UUID NOT NULL REFERENCES "Evidence"("id"),"weightOrder" INTEGER NOT NULL,PRIMARY KEY("stanceId","evidenceId"));
CREATE TABLE "CampaignResponse" ("id" UUID PRIMARY KEY,"candidateId" UUID NOT NULL REFERENCES "Candidate"("id"),"issueVersionId" UUID NOT NULL REFERENCES "IssueVersion"("id"),"answer" "PublicStanceLabel" NOT NULL,"explanation" TEXT,"verifiedSubmitter" BOOLEAN NOT NULL DEFAULT false,"submittedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "CorrectionCase" ("id" UUID PRIMARY KEY,"targetType" TEXT NOT NULL,"targetId" UUID NOT NULL,"submitterType" TEXT NOT NULL,"state" TEXT NOT NULL,"resolution" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "AuditEvent" ("id" UUID PRIMARY KEY,"actorId" UUID,"action" TEXT NOT NULL,"entityType" TEXT NOT NULL,"entityId" UUID NOT NULL,"beforeJson" JSONB,"afterJson" JSONB,"timestamp" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "ResearchJob" ("id" UUID PRIMARY KEY,"candidateId" UUID NOT NULL REFERENCES "Candidate"("id"),"issueVersionId" UUID REFERENCES "IssueVersion"("id"),"sourceScope" TEXT NOT NULL,"status" TEXT NOT NULL,"startedAt" TIMESTAMP(3),"finishedAt" TIMESTAMP(3));
